'use strict';
let socialAfter=0,socialBusy=false,socialFriends=[],socialTrade=null,socialChannel='',socialUnread=0,socialTradeBusy=false;
window.playerTrade=false;
const socialRoot=document.createElement('section');socialRoot.id='socialPanel';socialRoot.hidden=true;socialRoot.setAttribute('aria-label','Chat and friends');
socialRoot.innerHTML='<header><button id="localChatTab">Local</button><button id="friendsChatTab">Friends</button><button id="closeSocial" aria-label="Close chat">×</button></header><div id="tradeInvitation" hidden></div><div id="chatPane"><div id="chatChannel">Local chat</div><div id="chatMessages" role="log" aria-live="polite"></div><form id="chatForm"><input id="chatText" aria-label="Chat message" maxlength="250" autocomplete="off" placeholder="Say something…"><button aria-label="Send message">➤</button></form></div><div id="friendsPane" hidden><form id="friendForm"><input id="friendUsername" aria-label="Account username" maxlength="20" placeholder="Account username"><button>Add</button></form><div id="friendsList"></div><h3>Nearby players</h3><div id="nearbyPlayers"></div></div><p id="socialError" role="status"></p>';
document.body.appendChild(socialRoot);
const chatToggle=document.createElement('button');chatToggle.id='chatToggle';chatToggle.title='Chat and friends';chatToggle.setAttribute('aria-label','Chat and friends');chatToggle.innerHTML='<svg viewBox="0 0 32 32" aria-hidden="true"><path d="M3 4h26v19H14l-8 6v-6H3z" fill="#c7ba93" stroke="#534d37" stroke-width="2"/><path d="M8 10h16M8 16h12" stroke="#534d37" stroke-width="2"/></svg>';document.body.appendChild(chatToggle);
const tradeDialog=document.createElement('dialog');tradeDialog.id='playerTradeDialog';tradeDialog.setAttribute('aria-label','Player trade');document.body.appendChild(tradeDialog);tradeDialog.addEventListener('cancel',e=>{e.preventDefault();tradeAction('cancelTrade');});
function socialError(text=''){$('socialError').textContent=text;const e=$('tradeError');if(e)e.textContent=text;}
function addServiceMessage(text){const p=document.createElement('p');p.className='service-message';p.textContent=text;$('chatMessages').appendChild(p);}
function appendChat(message){const p=document.createElement('p');p.dataset.private=message.recipient?'yes':'no';p.dataset.peer=message.author===accountUsername?message.recipient:message.author;p.textContent=(message.recipient?'[Private] ':'')+message.author+': '+message.body;p.hidden=!!socialChannel&&(p.dataset.private!=='yes'||p.dataset.peer!==socialChannel);$('chatMessages').appendChild(p);while($('chatMessages').children.length>100)$('chatMessages').firstElementChild.remove();$('chatMessages').scrollTop=$('chatMessages').scrollHeight;if(socialRoot.hidden){socialUnread++;chatToggle.setAttribute('aria-label','Chat and friends · '+socialUnread+' new messages');chatToggle.classList.add('unread');}}
function openSocial(friends=false){socialRoot.hidden=false;socialUnread=0;chatToggle.classList.remove('unread');$('chatPane').hidden=friends;$('friendsPane').hidden=!friends;if(friends)renderFriends();}
function selectChat(username=''){socialChannel=username;openSocial();$('chatChannel').textContent=username?'Private · '+username:'Local chat';for(const p of $('chatMessages').children)p.hidden=!!username&&(p.dataset.private!=='yes'||p.dataset.peer!==username);$('chatText').focus();}
chatToggle.onclick=()=>{if(socialRoot.hidden)openSocial();else socialRoot.hidden=true;};$('closeSocial').onclick=()=>socialRoot.hidden=true;$('localChatTab').onclick=()=>selectChat();$('friendsChatTab').onclick=()=>openSocial(true);
async function socialPost(body){const r=await fetch('/api/social',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:AbortSignal.timeout(8000)});const result=await r.json();if(!r.ok)throw new Error(result.error||'Unable to reach other players.');return result;}
$('chatForm').onsubmit=async e=>{e.preventDefault();const text=$('chatText').value.trim();if(!text)return;try{await socialPost({action:'message',text,username:socialChannel||undefined});$('chatText').value='';socialError();await pollSocial();}catch(e){socialError(e.message);}};
$('friendForm').onsubmit=async e=>{e.preventDefault();await friendAction('friend',$('friendUsername').value.trim());};
async function friendAction(action,username){try{await socialPost({action,username});socialError();await pollSocial();}catch(e){socialError(e.message);toast(e.message);}}
function socialButton(text,fn){const b=document.createElement('button');b.textContent=text;b.onclick=fn;return b;}
function renderFriends(){
 const list=$('friendsList');list.replaceChildren();if(!socialFriends.length){const p=document.createElement('p');p.textContent='Add a friend using their account username.';list.appendChild(p);}
 for(const f of socialFriends){const row=document.createElement('div'),name=document.createElement('span');name.textContent=f.username+' · '+(f.status==='accepted'?(f.online?'Online':'Offline'):f.incoming?'Friend request':'Request sent');row.appendChild(name);
 if(f.status==='accepted')row.appendChild(socialButton('Message',()=>selectChat(f.username)));else if(f.incoming)row.appendChild(socialButton('Accept',()=>friendAction('acceptFriend',f.username)));
 row.appendChild(socialButton(f.status==='accepted'?'Remove':'Decline',()=>friendAction('removeFriend',f.username)));list.appendChild(row);}
 const nearby=$('nearbyPlayers');nearby.replaceChildren();if(onlineScene===currentScene)for(const p of onlinePeers.values()){if(!p.username||Math.hypot(p.x-px,p.y-py)>12)continue;const row=document.createElement('div'),label=document.createElement('span');label.textContent=p.name+' (@'+p.username+')';row.append(label,socialButton('Add friend',()=>friendAction('friend',p.username)),socialButton('Trade',()=>requestPlayerTrade(p.username)));nearby.appendChild(row);}
}
async function preparePlayerTrade(){
 if(window.playerTrade)return true;if(activeEncounter||playerAttackMotion){throw new Error('Finish combat before trading.');}if($('modal').open||$('creator').open||$('spiritsDialog').open)throw new Error('Close the current interface before trading.');
 stop();queueCloudSave();if(cloudBusy)throw new Error('Your progress is saving. Try again in a moment.');await flushCloudSave();if(cloudDirty||cloudDisconnected||cloudConflict)throw new Error('Your character must finish saving before trading.');window.playerTrade=true;return true;
}
async function requestPlayerTrade(username){if(socialTradeBusy)return;socialTradeBusy=true;try{await preparePlayerTrade();const result=await socialPost({action:'requestTrade',username});socialTrade=result.trade;renderPlayerTrade();socialError();}catch(e){window.playerTrade=false;socialError(e.message);toast(e.message);}finally{socialTradeBusy=false;}}
async function tradeAction(action,offer){if(!socialTrade||socialTradeBusy)return;socialTradeBusy=true;try{if(action==='acceptTrade')await preparePlayerTrade();const r=await socialPost({action,id:socialTrade.id,revision:socialTrade.revision,offer});socialTrade=r.trade;renderPlayerTrade();socialError();}catch(e){if(socialTrade.status==='pending'&&socialTrade.incoming&&!tradeDialog.open)window.playerTrade=false;await pollSocial();socialError(e.message);}finally{socialTradeBusy=false;}}
function offerSummary(offer){return [offer.gold.toLocaleString()+' coins',...offer.items.map(e=>(ITEMS[e.id]?.name||e.id)+' × '+e.count.toLocaleString())];}
function renderPlayerTrade(){
 const t=socialTrade;if(!t)return;$('tradeInvitation').hidden=!(t.incoming&&t.status==='pending'&&!window.playerTrade);
 if(t.incoming&&t.status==='pending'&&!window.playerTrade){openSocial(true);const box=$('tradeInvitation'),p=document.createElement('p');box.replaceChildren();p.textContent=t.username+' wants to trade.';p.append(socialButton('Accept',()=>tradeAction('acceptTrade')),socialButton('Decline',()=>tradeAction('cancelTrade')));box.appendChild(p);return;}
 if(!window.playerTrade)return;
 if(!tradeDialog.open)tradeDialog.showModal();tradeDialog.replaceChildren();const title=document.createElement('h2');title.textContent='Trade with '+t.username;tradeDialog.appendChild(title);
 if(['complete','cancelled'].includes(t.status)){const p=document.createElement('p');p.textContent=t.status==='complete'?'Trade complete. Your items are saved.':'Trade cancelled. No items changed hands.';tradeDialog.append(p,socialButton('Return to game',()=>location.reload()));return;}
 if(t.status==='pending'){const p=document.createElement('p');p.textContent='Waiting for '+t.username+' to accept…';tradeDialog.appendChild(p);}else{
  const columns=document.createElement('div');columns.className='trade-offers';for(const [heading,offer]of [['You give',t.mine],[t.username+' gives',t.theirs]]){const section=document.createElement('section'),h=document.createElement('h3');h.textContent=heading;section.appendChild(h);for(const text of offerSummary(offer)){const p=document.createElement('p');p.textContent=text;section.appendChild(p);}columns.appendChild(section);}tradeDialog.appendChild(columns);
  const form=document.createElement('form');form.className='trade-edit';const item=document.createElement('select');item.setAttribute('aria-label','Item to offer');const none=document.createElement('option');none.value='';none.textContent='Choose bag item';item.appendChild(none);for(const [id,entry]of Object.entries(ITEMS)){const n=spareItemCount(id);if(n>0){const o=document.createElement('option');o.value=id;o.textContent=entry.name+' ('+n+')';item.appendChild(o);}}
  const quantity=document.createElement('input');quantity.type='number';quantity.min='0';quantity.max='1000000000';quantity.value='1';quantity.setAttribute('aria-label','Item quantity, zero removes it');const coins=document.createElement('input');coins.type='number';coins.min='0';coins.max=String(s.gold);coins.value=String(t.mine.gold);coins.setAttribute('aria-label','Coins offered');const submit=document.createElement('button');submit.textContent='Update offer';form.append(item,quantity,coins,submit);form.onsubmit=e=>{e.preventDefault();const items=t.mine.items.filter(e=>e.id!==item.value);if(item.value&&Number(quantity.value)>0)items.push({id:item.value,count:Number(quantity.value)});tradeAction('offer',{gold:Number(coins.value),items});};tradeDialog.appendChild(form);
  const review=document.createElement('p');review.textContent=t.peerConfirmed?'The other player has confirmed. Check both offers carefully.':'Check both offers. Any change clears both confirmations.';tradeDialog.appendChild(review);const confirm=socialButton(t.confirmed?'Confirmed · waiting':'Confirm this trade',()=>tradeAction('confirmTrade'));confirm.disabled=t.confirmed;tradeDialog.appendChild(confirm);
 }
 const error=document.createElement('p');error.id='tradeError';error.setAttribute('role','alert');tradeDialog.append(error,socialButton('Cancel trade',()=>tradeAction('cancelTrade')));
}
async function pollSocial(){
 if(socialBusy||!cloudReady||!assetsReady||cloudDisconnected||!s.character)return;socialBusy=true;
 try{const r=await fetch('/api/social?after='+socialAfter+(socialTrade?'&trade='+encodeURIComponent(socialTrade.id):''),{cache:'no-store',signal:AbortSignal.timeout(5000)});if(!r.ok)return;const data=await r.json();for(const m of data.messages){if(m.id>socialAfter){appendChat(m);socialAfter=Math.max(socialAfter,m.id);}}socialFriends=data.friends;if(!$('friendsPane').hidden)renderFriends();if(data.trade&&(data.trade.id!==socialTrade?.id||data.trade.revision>socialTrade?.revision)){socialTrade=data.trade;renderPlayerTrade();}if(socialTrade?.status==='cancelled'&&!window.playerTrade)socialTrade=null;}
 catch{}finally{socialBusy=false;}
}
setInterval(pollSocial,1500);
document.addEventListener('keydown',e=>{if(e.key!=='Enter'||e.target.closest?.('input,textarea,select,button,dialog,[contenteditable]')||cloudDisconnected||!assetsReady)return;e.preventDefault();selectChat(socialChannel);});
